import assert from 'node:assert/strict'
import { toolsUsedInGcode, colorStartCommand } from '../server/printer/klipper.ts'

// Der AD5X holt den Slot beim Wechsel aus mod_data/file.json. Nur PRINT_ZCOLOR
// schreibt diese Zuordnung, deshalb muss die App sie beim Start mitschicken.
// Werkzeug n gehört zu Slot n+1 — der Slicer gibt den Slot-Index als Werkzeug aus.

const sample = [
  '; generated by Easy-Slicer',
  '; T0 ist hier nur ein Kommentar',
  'START_PRINT EXTRUDER_TEMP=215 BED_TEMP=60 MESH=60',
  'M104 S215 T0 ; Parameter, kein Werkzeugwechsel',
  'G1 X10 Y10',
  '_A_CHANGE_FILAMENT CHANNEL=0',
  'G1 X20 Y20',
  '_A_CHANGE_FILAMENT CHANNEL=1 RESTORE_TEMP=1',
  'T2',
  'G1 X30 Y30',
].join('\n')

assert.deepEqual(toolsUsedInGcode(sample), [0, 1, 2], 'Werkzeuge aus Wechselbefehlen und T-Codes')

// Reine Kommentare und Temperatur-Parameter dürfen keine Werkzeuge erfinden.
assert.deepEqual(
  toolsUsedInGcode(['; T0', 'M104 S215 T1', 'M109 S210 T0'].join('\n')),
  [],
  'Kommentare und Parameter zählen nicht',
)

// Einfarbig: kein Startbefehl, der bisherige Weg bleibt.
assert.equal(colorStartCommand('teil.gcode', []), null, 'ohne Wechsel kein PRINT_ZCOLOR')

assert.equal(
  colorStartCommand('teil.gcode', [0, 1]),
  'PRINT_ZCOLOR FILENAME="teil.gcode" PLATE=1 ALLOWED_TOOL_COUNT=2 T0=1 T1=2',
  'zwei Werkzeuge auf Slot 1 und 2',
)

// Lücken sind erlaubt: Slot 2 und 4 belegen Werkzeug 1 und 3.
assert.equal(
  colorStartCommand('teil.gcode', [3, 1, 1]),
  'PRINT_ZCOLOR FILENAME="teil.gcode" PLATE=1 ALLOWED_TOOL_COUNT=2 T1=2 T3=4',
  'doppelte Werkzeuge fallen weg, Lücken bleiben',
)

console.log(
  'OK: AD5X-Start — Werkzeuge 0/1/2 erkannt, Kommentare und T-Parameter ignoriert, ' +
    'Startbefehl T0=1 T1=2 bzw. T1=2 T3=4, einfarbig ohne PRINT_ZCOLOR.',
)
